async def apply_full_merge(force: bool = False) -> dict:
    """Применяет полное объединение балансов, уровней XP и бизнесов."""
    import db
    
    if not force:
        done = await db.get_setting(0, "merge_22_03_applied", "0")
        if done == "1":
            return {"applied": False, "reason": "already_applied"}

    log.info("Запуск объединения баз 22 и 03 числа...")
    now = int(time.time())
    users_updated = 0
    stats_updated = 0
    biz_updated = 0

    # 1. Восстанавливаем балансы пользователей
    for uid, (uname, fname, bal) in MERGED_USERS.items():
        row = await db.fetchone("SELECT balance FROM users WHERE user_id=?", (uid,))
        if row:
            cur_b = row["balance"]
            # Пользователь просил: соединить 22 и 03, не затирать больший баланс
            new_b = max(cur_b, bal)
            await db.execute(
                "UPDATE users SET balance=?, username=COALESCE(NULLIF(username,''),?), first_name=COALESCE(NULLIF(first_name,''),?) WHERE user_id=?",
                (new_b, uname, fname, uid)
            )
            users_updated += 1
        else:
            await db.execute(
                "INSERT INTO users (user_id, username, first_name, balance, bank, xp, rep, messages, grams, created_at) "
                "VALUES (?, ?, ?, ?, 0, 100, 0, 0, 0, ?)",
                (uid, uname, fname, bal, now)
            )
            users_updated += 1

    # 2. Восстанавливаем игровой уровень и опыт XP (game_stats)
    for uid, (xp, played, won) in MERGED_STATS.items():
        await db.execute(
            "INSERT INTO game_stats (user_id, xp, games_played, games_won) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(user_id) DO UPDATE SET xp=MAX(xp, excluded.xp), games_played=MAX(games_played, excluded.games_played), games_won=MAX(games_won, excluded.games_won)",
            (uid, xp, played, won)
        )
        stats_updated += 1

    # 3. Восстанавливаем все предприятия
    for uid, bkey, cnt in MERGED_BIZ:
        await db.execute(
            "INSERT INTO user_businesses (user_id, biz_key, count, last_collect) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(user_id, biz_key) DO UPDATE SET count=MAX(count, excluded.count)",
            (uid, bkey, cnt, now)
        )
        biz_updated += 1

    await db.set_setting(0, "merge_22_03_applied", "1")
    log.info("Объединение успешно завершено: %d пользователей, %d статов, %d бизнесов", users_updated, stats_updated, biz_updated)

    return {
        "applied": True,
        "users_updated": users_updated,
        "stats_updated": stats_updated,
        "biz_updated": biz_updated
    }
